  ui_story_40160001_24_dialog_content = "Aku sudah mencoba penelitian serupa, tapi dengan efek yang sedikit. Sering kali, Eclipsite akan mencoba menyerang setiap Aurorian yang mereka lihat, dan itu saja.",
