  ui_story_40160001_26_dialog_content = "*Bersembunyi di sudut*",
  ui_story_40160001_27_dialog_content = "Tapi baru kali ini aku melihat Eclipsite yang penakut. Ia bisa menjadi subjek tes yang berguna.",
