  ui_story_40160001_49_dialog_content = "\"Hollow Gaze\" milikku bisa mengambil alih pikirannya, mengaburkan penilaiannya, dan memaksa dia untuk secara tidak sadar menjawab pertanyaan-pertanyaanku.",
  ui_story_40160001_50_dialog_content = "Kecuali Eclipsite ini benar-benar tidak ada niat untuk menyerang.",
  ui_story_40160001_51_dialog_content = "Haha, bagiku itu tidak akan ada gunanya di sini—kemampuan itu sama sekali tidak bekerja, meskipun kedengarannya memang mengesankan.",
  ui_story_40160001_52_dialog_content = "Cukup, Benny.",
  ui_story_40160001_53_dialog_content = "Jika kemampuanku tidak cukup kuat, mungkin kau ingin mencobanya?",
