  ui_story_40160001_65_dialog_content = "Sudah, sudah, jangan saling bertengkar. Ini juga berlaku untukmu, Eicy. Jangan sembarangan menggunakan kemampuanmu pada temanmu!",
  ui_story_40160001_66_dialog_content = "<size=45>Heh! Minta maaf padaku, sekarang!</size>",
  ui_story_40160001_67_dialog_content = "Katamu kau ingin mencobanya. Kenapa aku harus meminta maaf?",
  ui_story_40160001_68_dialog_content = "Huu-huu...",
