  ui_story_40160001_76_dialog_content = "Eh!? Aku-aku...!",
  ui_story_40160001_77_dialog_content = "Tiba-tiba ia menjadi sedikit bersemangat setelah diikat...?",
  ui_story_40160001_78_dialog_content = "Owww... Owww...",
  ui_story_40160001_79_dialog_content = "...",
  ui_story_40160001_80_dialog_content = "Apa kau mencoba... bertingkah seperti manusia dengan isak tangis itu?",
  ui_story_40160001_81_dialog_content = "Owww... Aku... tidak... Hanya, makan...",
  ui_story_40160001_82_dialog_content = "Apa yang kamu makan?",
  ui_story_40160001_83_dialog_content = "Makan... Makan...",
  ui_story_40160001_84_dialog_content = "Sepertinya kamu memakan...",
