  ui_story_40160001_86_dialog_content = "Corax, apa yang akan kamu lakukan?",
  ui_story_40160001_87_dialog_content = "Jika aku <color=#FFB400>membedahnya</color>, aku bisa tahu apa yang dimakannya.",
  ui_story_40160001_88_option_content = "Membedah?",
  ui_story_40160001_89_dialog_content = "Tunggu... Bukankah kita sudah menetapkan bahwa kita di sini untuk menginterogasinya?",
  ui_story_40160001_90_dialog_content = "Bahkan aku tidak mencoba untuk membunuhnya! Aku hanya mencoba untuk menginterogasinya, oke?",
  ui_story_40160001_91_dialog_content = "Makhluk ini adalah sumber informasi yang sangat berharga, dan nilai penelitiannya pasti akan lebih tinggi jika dia dalam kondisi hidup.",
  ui_story_40160001_92_option_content = "Tunggu, singkirkan pisau bedah itu.",
  ui_story_40160001_93_dialog_content = "Kau tak bisa membedah Eclipsite di dalam kafe!",
  ui_story_40160001_94_dialog_content = "Benar juga, orang-orang bisa mengira kita sedang menyajikannya untuk makan siang.",
  ui_story_40160001_95_dialog_content = "Duduk di kafe yang dibanjiri darah Eclipsite, minum kopi... Haha, lumayan juga.",
  ui_story_40160001_96_dialog_content = "Hentikan! Jangan bedah dia!",
  ui_story_40160001_97_dialog_content = "...",
  ui_story_40160001_98_dialog_content = "Maaf, aku akan menenangkan diriku...",
  ui_story_40160001_99_dialog_content = "Omong-omong, mari kita lanjutkan.",
  ui_story_40160001_100_dialog_content = "Karena Eclipsite ini bisa berbicara, kita hanya perlu terus menginterogasinya. Kita tidak perlu teknik-teknik rumit ini...",
  ui_story_40160001_101_dialog_content = "Sepertinya kamu masih belum mengerti kekuatan dari \"Hollow Gaze\"? Kita perlu mencobanya lagi?",
  ui_story_40160001_102_dialog_content = "<size=45>Ya, benar sekali. Aku tadi membicarakanmu!</size>",
  ui_story_40160001_103_dialog_content = "Jika kita menemukan sesuatu darinya...",
  ui_story_40160001_104_dialog_content = "Hei, penutup mata! <size=45>Minta maaf padaku!</size>",
  ui_story_40160001_105_dialog_content = "Oke, baiklah. Omong-omong... <size=45>Kamu juga memakai penutup mata!</size>",
  ui_story_40160001_106_dialog_content = "Baiklah! Sudah selesai!",
  ui_story_40160001_107_dialog_content = "Hei! Eclipsite!",
  ui_story_40160001_108_dialog_content = "<anim type=Shake><size=35>Hik...</size></anim>",
  ui_story_40160001_109_dialog_content = "Kamu punya nama? Bukankah kalian yang berkelas atas punya nama?",
  ui_story_40160001_110_dialog_content = "Aku, aku...",
  ui_story_40160001_111_dialog_content = "Jika kamu bisa berbicara, bicaralah sekarang, sebelum aku menarik lidahmu keluar.",
  ui_story_40160001_112_dialog_content = "Aku... punya...",
  ui_story_40160001_113_dialog_content = "Tidak apa-apa. Kamu tidak perlu takut pada Aurorian jahat itu. Beri tahu aku namamu. Aku bisa membantumu.",
  ui_story_40160001_114_dialog_content = "Nama... Nama...",
  ui_story_40160001_115_dialog_content = "<size=45>Siapa namamu! <anim type=Shake>Jawab sekarang sebelum aku menembakmu!</anim></size>",
  ui_story_40160001_116_dialog_content = "Curo! Ia sudah hampir berbicara. Kenapa kamu mengganggu? Kamu bodoh, ya?!",
  ui_story_40160001_117_dialog_content = "Kita akan menginterogasinya atau bagaimana? Kau pernah mendengar tentang \"Metode Interogasi Benny dan Curo\" yang legendaris?",
  ui_story_40160001_118_dialog_content = "\"Metode Interogasi Benny dan Curo\"... Apa itu?",
  ui_story_40160001_119_dialog_content = "Di metode itu, ada satu interogator yang berperan sebagai \"polisi baik,\" dan yang satu lagi berperan sebagai \"polisi jahat.\"",
  ui_story_40160001_120_dialog_content = "Polisi jahat mengintimidasi tersangkanya, agar dia terpaksa mengandalkan polisi baik untuk meminta dukungan emosional.",
  ui_story_40160001_121_dialog_content = "Cara ini akan membuat tersangka menurunkan kewaspadaannya sehingga dia lebih memilih menjawab pertanyaan polisi baik.",
  ui_story_40160001_122_dialog_content = "Oh, begitu... Tapi mereka bertengkar hebat!",
  ui_story_40160001_123_dialog_content = "Itulah yang seharusnya kamu lakukan saat sedang mengancam seseorang! Apa kesalahanku!?",
  ui_story_40160001_124_dialog_content = "Lalu apa omong kosong tentang \"menembakmu\" ini? Apakah kau benar-benar memiliki pistol?",
  ui_story_40160001_125_dialog_content = "Tahu tidak apa masalahmu? Bahkan saat kamu berpura-pura menjadi \"polisi baik\", kamu tidak bisa berhenti menggertakkan gigimu pada semua orang seperti anjing gila!",
  ui_story_40160001_126_dialog_content = "Eng... Kenapa kalian tidak bertukar peran? Kali ini, Benny bisa menjadi \"polisi jahat\", dan Curo bisa menjadi \"polisi baik\".",
  ui_story_40160001_127_dialog_content = "Baik! Aku akan menunjukkan kepadamu seperti apa \"polisi jahat\" yang sebenarnya!",
  ui_story_40160001_128_dialog_content = "<size=45>Hei! Siapa namamu!? Cepat! Jawab aku sekarang atau kutembak!</size>",
  ui_story_40160001_129_dialog_content = "Aku... Oww..",
  ui_story_40160001_130_dialog_content = "Jangan takut. Santai saja.",
  ui_story_40160001_131_dialog_content = "*Mundur*",
  ui_story_40160001_132_dialog_content = "Jangan khawatir. Tak perlu takut. Kemarilah... Nah, begitu...",
  ui_story_40160001_133_dialog_content = "*Mundur*",
  ui_story_40160001_134_dialog_content = "Ahaha! Curo, Eclipsite ini takut setengah mati padamu! Seperti ini caramu mencoba bersikap ramah?",
  ui_story_40160001_135_dialog_content = "...",
  ui_story_40160001_136_dialog_content = "Aku akan menunjukkan padamu seperti apa pedangku...",
  ui_story_40160001_137_dialog_content = "<size=45>Lihat dirimu, menggunakan kekerasan saat kehabisan kata-kata?</size>",
  ui_story_40160001_138_dialog_content = "Ayo! Mari kita mulai lagi <size=45><color=#FFB400>Pertempuran Benny dan Curo</color></size>...!",
  ui_story_40160001_139_dialog_content = "Mereka begitu lagi...",
  ui_story_40160001_140_dialog_content = "Hei!",
  ui_story_40160001_141_dialog_content = "Pistol jenis apa yang ingin kamu gunakan, Penutup Mata? Semua peluru ada di sini bersamaku!",
  ui_story_40160001_142_dialog_content = "Hah! <size=45>Dan pelawak bermata tak berguna ini mengira dia berhak untuk mengejek!?</size>",
  ui_story_40160001_143_dialog_content = "<size=50>Apa katamu!?</size>",
  ui_story_40160001_144_dialog_content = "Erm... Kenapa tiba-tiba ini berubah menjadi pertengkaran hebat!?",
  ui_story_40160001_145_dialog_content = "Jika hanya ingin bertarung, kalian bisa pergi dari sini sekarang!",
  ui_story_40160001_146_dialog_content = "Bagus, PlayerName. Kau hanya perlu satu detik untuk menghentikannya.",
  ui_story_40160001_147_dialog_content = "Ah... Kacau sekali... Kita bahkan belum mengatasi masalah Eclipsite ini.",
  ui_story_40160001_148_dialog_content = "Jangan khawatir. Aku berhasil mengonfirmasi satu hal sebagai kesimpulan dari kejadian ini.",
  ui_story_40160001_149_dialog_content = "Apa itu?",
  ui_story_40160001_150_dialog_content = "PlayerName, kamu bisa menggunakan kemampuan psikismu?",
  ui_story_40160001_151_dialog_content = "Akan kucoba.",
  ui_story_40160001_152_dialog_content = "*Jadi mengantuk*",
  ui_story_40160001_153_dialog_content = "(Ingatan siapa yang kamu lihat?)",
  ui_story_40160001_154_dialog_content = "Jangan makan... Makan... Jangan makan... Makan...",
  ui_story_40160001_155_dialog_content = "(Apakah ia sedang menghitung cakarnya?)",
  ui_story_40160001_156_dialog_content = "Jangan makan... makan... jangan makan... makan...?",
  ui_story_40160001_157_dialog_content = "Sangat lapar...",
  ui_story_40160001_158_dialog_content = "(Makhluk ini mengobrak-abrik lemari...)",
  ui_story_40160001_159_dialog_content = "Aku melihat sesuatu...",
  ui_story_40160001_160_dialog_content = "Haha... Apa yang kamu lihat mungkin adalah situasi yang baru saja aku ingat...",
  ui_story_40160001_161_dialog_content = "Kenapa kamu dekat sekali denganku!?",
  ui_story_40160001_162_dialog_content = "Aku ingin memastikan kamu bisa merasakan gambar dalam pikiranku.",
  ui_story_40160001_163_dialog_content = "Kupikir tadi kamu ingin aku merasakan pikiran Eclipsite itu?",
  ui_story_40160001_164_dialog_content = "Kenapa? Bukankah lebih cepat untuk bertanya langsung padaku?",
  ui_story_40160001_165_dialog_content = "Kupikir kita ada di sini untuk menginterogasi Eclipsite, bukan kamu!",
  ui_story_40160001_166_dialog_content = "Benar.",
  ui_story_40160001_167_dialog_content = "Hei, kamu tadi makan steik di lemari itu, 'kan?",
  ui_story_40160001_168_dialog_content = "Oww... M-maaf...",
  ui_story_40160001_169_dialog_content = "Berapa banyak yang kamu makan?",
  ui_story_40160001_170_dialog_content = "Dua... tiga...",
  ui_story_40160001_171_dialog_content = "Lalu setelahnya, apa yang kamu lakukan?",
  ui_story_40160001_172_dialog_content = "S-seseorang... berkata...",
  ui_story_40160001_173_dialog_content = "Eh...",
  ui_story_40160001_174_dialog_content = "Tak apa, santai saja.",
  ui_story_40160001_175_dialog_content = "Makan... bereskan... bersihkan...",
  ui_story_40160001_176_dialog_content = "Seperti... ini...",
  ui_story_40160001_177_dialog_content = "*Memungut sampah di tanah dan membuangnya ke tempat sampah*",
  ui_story_40160001_178_dialog_content = "Aneh sekali. Pertarungan mereka barusan membuat kafe ini menjadi berantakan, tapi Eclipsite ini yang membersihkannya.",
  ui_story_40160001_179_dialog_content = "Kami bisa mendengarmu, tahu...",
  ui_story_40160001_180_dialog_content = "Oh? Kalian sudah selesai bertengkar?",
  ui_story_40160001_181_dialog_content = "Sepertinya itu berakhir dengan pertarungan antara gadis berbaju merah dan gadis berbaju hitam.",
  ui_story_40160001_182_dialog_content = "Aku dan pria itu tadi... Siapa namanya?",
  ui_story_40160001_183_dialog_content = "Corax.",
  ui_story_40160001_184_dialog_content = "Nah... Sepertinya yang bisa kita lakukan sekarang hanya menyingkir dan menonton mereka bertarung habis-habisan.",
  ui_story_40160001_185_dialog_content = "Migard!",
  ui_story_40160001_186_dialog_content = "Kau sudah tahu kebenarannya sejak awal?",
  ui_story_40160001_187_dialog_content = "Ya.",
  ui_story_40160001_188_dialog_content = "Kalau begitu, kenapa kamu mengundang kami kemari?",
  ui_story_40160001_189_option_content = "Ya, itu yang ingin aku tahu...",
  ui_story_40160001_190_dialog_content = "Sangat sederhana. Bagaimanapun, ini adalah sampel penelitian yang berharga. Tentu saja, aku harus melakukan segala jenis eksperimen padanya.",
  ui_story_40160001_191_dialog_content = "Hah? Maksudmu, kamu memanggil kami kemari untuk menjadi subjek tesmu juga?",
  ui_story_40160001_192_dialog_content = "Yah, aku tak akan menyangkal bahwa kalian juga adalah <color=#FFB400>spesimen penelitian</color> dalam situasi ini.",
  ui_story_40160001_193_dialog_content = "PlayerName, apa tindakanmu selanjutnya?",
  ui_story_40160001_194_dialog_content = "Aku...",
  ui_story_40160001_195_dialog_content = "*Pergi dengan berjalan tak tentu arah*",
  ui_story_40160001_196_dialog_content = "Kamu membiarkan Eclipsite itu pergi begitu saja?",
  ui_story_40160001_197_dialog_content = "Apakah makhluk aneh yang berjalan konyol seperti itu benar-benar Eclipsite?",
  ui_story_40160001_198_dialog_content = "Ada orang-orang yang bersimpati terhadap Eclipsite, dan mereka yang ingin bersekutu dengan Eclipsite, dan tentu saja, kisah-kisah semacam ini memang ada.",
  ui_story_40160001_199_dialog_content = "Namun, dalam cerita-cerita ini, PlayerName, nasib orang-orang ini sering kali berubah menjadi lebih buruk setelah tirainya ditutup.",
  ui_story_40160001_200_dialog_content = "Jadi, kau memperlakukan kami semua sebagai subjek tes, tapi masih berani mengatakan hal seperti itu?",
  ui_story_40160001_201_dialog_content = "Benny, kau sedang berbicara dengan anggota Illumina.",
  ui_story_40160001_202_dialog_content = "Aku tahu!",
  ui_story_40160001_203_dialog_content = "Aku tak punya simpati untuk Eclipsite. Aku masih akan memilih untuk melenyapkan mereka kapan pun diperlukan. Pilihanku belum berubah...",
  ui_story_40160001_204_dialog_content = "Tapi hari ini, kau memutuskan untuk membebaskan satu Eclipsite?",
  ui_story_40160001_205_dialog_content = "Apakah kamu menolak keputusanku tentang membiarkannya pergi?",
  ui_story_40160001_206_dialog_content = "Tidak ada kejahatan yang dilakukan, jadi tidak ada hukuman yang perlu diberikan. Berdasarkan prinsip pribadiku... Aku tak keberatan membiarkannya pergi.",
  ui_story_40160001_207_dialog_content = "Tidak, aku sudah mendapatkan data eksperimen yang kuinginkan. Kau bisa melakukan apa pun yang kamu mau dengannya.",
  ui_story_40160001_208_dialog_content = "Kita tidak bisa membunuhnya, dan kita tidak bisa membiarkannya di Colossus. Kita hanya bisa membebaskannya dan membiarkannya berjuang sendiri.",
  ui_story_40160001_209_dialog_content = "Kenapa begitu?",
  ui_story_40160001_210_dialog_content = "Corax, jika itu terserah kamu, setelah tahu semua yang dilakukannya... apakah kamu masih ingin membedahnya?",
  ui_story_40160001_211_dialog_content = "...",
  ui_story_40160001_212_dialog_content = "Tidak, kita harus bisa membedakan mana yang benar dan yang salah dengan lebih baik daripada Eclipsite itu.",
  ui_story_40160001_213_dialog_content = "Jadi, itu alasanmu.",
  ui_story_40160001_214_dialog_content = "Ini membosankan sekali. Kenapa kita harus peduli dengan semua ini...?",
  ui_story_40160001_215_dialog_content = "PlayerName, sepertinya yang dimaksud Benny adalah kamu berhak untuk mengambil keputusan akhir, jadi kau tidak perlu terlalu memedulikan pendapat orang lain.",
  ui_story_40160001_216_dialog_content = "Yah, ini bukan kesimpulan yang buruk. Baguslah.",
  ui_story_40160001_217_dialog_content = "Migard, ada sesuatu yang lupa kutanyakan padamu...",
  ui_story_40160001_218_dialog_content = "Bagaimana kamu tahu bahwa ada Eclipsite yang menyelinap ke Colossus... dan bagaimana kamu melihat apa yang dilakukannya?",
  ui_story_40160001_219_dialog_content = "Yah, aku melihatnya setelah ia menyelinap masuk ke Colossus.",
  ui_story_40160001_220_dialog_content = "Aku menggunakan kemampuanku—Diving Spines. Begitu aku melihat Eclipsite itu, aku bisa melihat apa yang bisa dilihatnya.",
  ui_story_40160001_221_dialog_content = "Hah? Kemampuan luar biasa macam apa itu?",
  ui_story_40160001_222_dialog_content = "PlayerName, ini hanyalah contoh dari kekuatan ajaib Luminatics...",
  ui_story_40160001_223_dialog_content = "Tadi kebetulan saja saat aku melihat Eclipsite itu mencuri makanan...",
  ui_story_40160001_224_dialog_content = "Kemampuanku tidak cukup kuat untuk memantau segala hal yang terjadi di Colossus pada saat yang bersamaan.",
  ui_story_40160001_225_dialog_content = "\"Memantau\"? Kau baru saja bilang \"memantau\"?",
  ui_story_40160001_226_dialog_content = "Migard, apakah kamu pernah menggunakan kemampuanmu untuk... melakukan hal-hal yang seharusnya tidak kamu lakukan?",
  ui_story_40160001_227_dialog_content = "Aku sudah menjawab pertanyaan itu, PlayerName. Kebetulan saja aku melihatnya.",
  ui_story_40160001_228_dialog_content = "Oh, benarkah? Sepertinya, kita tidak akan mendengar apa yang sebenarnya terjadi dari Migard dalam waktu dekat ini, ya?",
  ui_story_40160001_229_dialog_content = "Kalau begitu, biarkan aku pergi dulu. Sampai jumpa.",
  ui_story_40160001_230_dialog_content = "Dia pergi?!",
  ui_story_40160001_231_dialog_content = "Apakah dia khawatir kami akan menginterogasinya?",
  ui_story_40160001_232_dialog_content = "PlayerName, apakah kamu ingin agar kami menginterogasinya? Ingin agar kami mendapatkan kebenaran darinya?",
  ui_story_40160001_233_dialog_content = "Hmm, biar kupikir...",
  ui_story_40160001_234_dialog_content = "<color=#FFB400>Master Interrogator</color> tepercayaku, kita harus membawanya ke ruangan yang tenang dan menguncinya terlebih dahulu...",
  ui_story_40160001_235_dialog_content = "Aku paham."
}
